AssistantMessageToolRequest(name='create', tool_call_id='tooluse_MNYrzj45bSEOUFZp9qlfS1', arguments={'file_text': '// Quiz definitions with correct answers
const CORRECT_ANSWERS = {
    q1: ['c', 'rust'],
    q2: ['typescript', 'javascript', 'php'],
    q3: ['typescript', 'rust']
};

// Initialize the quiz
document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('quizForm');
    form.addEventListener('submit', handleSubmit);
});

// Handle form submission
function handleSubmit(e) {
    e.preventDefault();

    const userAnswers = getUserAnswers();
    const results = evaluateAnswers(userAnswers);
    displayResults(results);
}

// Collect user's selected answers
function getUserAnswers() {
    const answers = {};

    ['q1', 'q2', 'q3'].forEach(question => {
        const checkboxes = document.querySelectorAll(`input[name="${question}"]:checked`);
        answers[question] = Array.from(checkboxes).map(cb => cb.value);
    });

    return answers;
}

// Evaluate answers against correct answers
function evaluateAnswers(userAnswers) {
    let correctCount = 0;
    const details = [];

    for (const [question, correct] of Object.entries(CORRECT_ANSWERS)) {
        const userAnswer = userAnswers[question] || [];
        const isCorrect = arraysEqual(userAnswer.sort(), correct.sort());

        if (isCorrect) {
            correctCount++;
        }

        details.push({
            question,
            userAnswer,
            correctAnswer: correct,
            isCorrect
        });
    }

    return {
        score: correctCount,
        total: 3,
        percentage: Math.round((correctCount / 3) * 100),
        details
    };
}

// Helper function to compare arrays
function arraysEqual(a, b) {
    if (a.length !== b.length) return false;
    return a.every((val, idx) => val === b[idx]);
}

// Display results to user
function displayResults(results) {
    const resultDiv = document.getElementById('result');
    let message = '';

    if (results.percentage === 100) {
        resultDiv.className = 'result-message success';
        message = `🎉 Perfect! You got all ${results.score}/${results.total} questions correct!`;
    } else if (results.percentage >= 66) {
        resultDiv.className = 'result-message success';
        message = `✓ Great job! You got ${results.score}/${results.total} questions correct (${results.percentage}%)`;
    } else {
        resultDiv.className = 'result-message error';
        message = `You got ${results.score}/${results.total} questions correct (${results.percentage}%). Try again!`;
    }

    resultDiv.innerHTML = message;
    resultDiv.style.display = 'block';

    // Scroll to results
    resultDiv.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}
